function Content(){const[items,setItems]=useState([]),[title,setTitle]=useState(''),[body,setBody]=useState(''),[message,setMessage]=useState(''),[editing,setEditing]=useState(null);const load=async()=>{const {data}=await supabase.from('house_contents').select('*').order('sort_order');setItems(data||[])};useEffect(()=>{load()},[]);const save=async()=>{if(!title.trim()||!body.trim()){setMessage('Preencha título e texto.');return}let q=editing?supabase.from('house_contents').update({title:title.trim(),body:body.trim()}).eq('id',editing):null;if(!editing){const {error}=await supabase.rpc('admin_create_house_content',{p_title:title.trim(),p_body:body.trim(),p_sort_order:items.length});if(error)setMessage(err(error));else{setTitle('');setBody('');load()}}else{const {error}=await q;if(error)setMessage(err(error));else{setTitle('');setBody('');setEditing(null);setMessage('Conteúdo atualizado.');load()}}};const remove=async id=>{if(!confirm('Excluir este conteúdo?'))return;const {error}=await supabase.from('house_contents').delete().eq('id',id);if(error)setMessage(err(error));else load()};return <div><h2>Conteúdos da casa</h2>{message&&<div className="toast">{message}</div>}<div className="card"><Field label="Título"><input className="input" value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="Texto"><textarea className="textarea" value={body} onChange={e=>setBody(e.target.value)}/></Field><div className="row"><button className="btn primary" onClick={save}>{editing?'Salvar edição':'Publicar'}</button>{editing&&<button className="btn" onClick={()=>{setEditing(null);setTitle('');setBody('')}}>Cancelar</button>}</div></div>{items.map(x=><div className="card" key={x.id}><span className="pill">{x.content_type}</span><h3>{x.title}</h3><p style={{whiteSpace:'pre-wrap'}}>{x.body}</p><div className="choice"><button className="btn" onClick={()=>{setEditing(x.id);setTitle(x.title);setBody(x.body)}}>Editar</button><button className="btn danger" onClick={()=>remove(x.id)}><Trash2 size={14}/> Excluir</button></div></div>)}</div>}

import React,{useEffect,useState} from 'react'
import {createRoot} from 'react-dom/client'
import {Home as HomeIcon,CalendarDays,Leaf,UserRound,WalletCards,BookOpen,ShieldCheck,LogOut,Check,X,Plus,RefreshCw,ChevronRight,Users,ClipboardList,Ticket,FileText,Save,Trash2,ArrowLeft} from 'lucide-react'
import {supabase} from './lib/supabase'
import {OrixaIcon,ORIXAS} from './orixaSymbols'
import './styles.css'
import './app.css'

const periods=[['friday','Sexta-feira'],['saturday_1430','Sábado · 14h30–15h30'],['saturday_post_gira','Sábado · pós-gira'],['sunday','Domingo']]
const kinds=[['ensinamento','Ensinamentos'],['reflexao','Reflexões'],['senti','O que senti']]
const groups=['Decoração','Cozinha','Comunicação','Manutenção','Organização']
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const dateTime=s=>new Date(s).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})
const period=k=>periods.find(x=>x[0]===k)?.[1]||k
const err=e=>e?.message||'Não foi possível concluir.'

function App(){
 const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[loading,setLoading]=useState(true),[screen,setScreen]=useState('home')
 const loadProfile=async u=>{if(!u){setProfile(null);return}const {data}=await supabase.from('profiles').select('*,groups(name)').eq('id',u.id).maybeSingle();setProfile(data)}
 useEffect(()=>{supabase.auth.getSession().then(async({data})=>{setSession(data.session);await loadProfile(data.session?.user);setLoading(false)});const {data:{subscription}}=supabase.auth.onAuthStateChange((_,s)=>{setSession(s);loadProfile(s?.user)});return()=>subscription.unsubscribe()},[])
 if(loading)return <div className="auth"><div className="card"><h2>Terreiro Pai Benedito do Congo</h2><p className="muted">Carregando…</p></div></div>
 if(!session)return <Auth/>
 if(!profile)return <div className="auth"><div className="card">Seu cadastro está sendo carregado…</div></div>
 const logout=async()=>{await supabase.auth.signOut();setScreen('home')}
 return <div className="app"><header className="top"><div className="logo">PBC</div><div><small>Terreiro Pai Benedito do Congo</small><strong>Axé, comunidade.</strong></div><div style={{marginLeft:'auto'}}><OrixaIcon name={profile.orixa_symbol} size={30}/></div></header><main className="content">{screen==='home'&&<Home p={profile} go={setScreen}/>} {screen==='giras'&&<Giras p={profile}/>} {screen==='community'&&<Community p={profile}/>} {screen==='me'&&<Me p={profile} go={setScreen} logout={logout}/>} {screen==='admin'&&profile.role==='admin'&&<Admin p={profile}/>} {screen==='admin'&&profile.role==='editor'&&<Admin p={profile} editor/>}</main><Birthday/><nav className="bottom"><div className="bottom-inner">{[['home','Início',HomeIcon],['giras','Giras',CalendarDays],['community','Comunidade',Leaf],['me','Eu',UserRound]].map(([id,label,Icon])=><button key={id} className={screen===id?'active':''} onClick={()=>setScreen(id)}><Icon size={20}/>{label}</button>)}</div></nav></div>
}

function Auth(){const [register,setRegister]=useState(false),[code,setCode]=useState(''),[invite,setInvite]=useState(null),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[dob,setDob]=useState(''),[orixa,setOrixa]=useState(''),[group,setGroup]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const validate=async()=>{const {data,error}=await supabase.rpc('validate_invitation',{p_code:code.trim()});if(error||!data?.length){setInvite(null);setMessage('Código inválido, usado, revogado ou expirado.');return}setInvite(data[0]);setName(data[0].intended_name||'');setEmail(data[0].intended_email||'');setMessage('Convite válido.')};const submit=async e=>{e.preventDefault();setBusy(true);setMessage('');try{if(register){if(!invite){await validate();return}if(!dob||!orixa||!group)throw new Error('Preencha data de nascimento, Orixá e grupo.');const {data,error}=await supabase.auth.signUp({email,password,options:{data:{name,invite_code:code.trim(),date_of_birth:dob,orixa_symbol:orixa,group_name:group}}});if(error)throw error;setMessage(data.session?'Conta criada. Entrando na casa…':'Conta criada. Agora você já pode entrar.')}else{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error}}catch(e){setMessage(err(e))}finally{setBusy(false)}};return <div className="auth"><div className="card"><div className="row"><div className="logo">PBC</div><span className="eyebrow">Terreiro Pai Benedito do Congo</span></div><h1>{register?'Entre para a casa.':'Bem-vindo de volta.'}</h1>{message&&<div className="toast">{message}</div>}<form onSubmit={submit}>{register&&<><Field label="Nome"><input className="input" value={name} onChange={e=>setName(e.target.value)} required/></Field><Field label="Código de convite"><div className="row"><input className="input" value={code} onChange={e=>setCode(e.target.value.toUpperCase())} required/><button className="btn" type="button" onClick={validate}>Validar</button></div></Field>{invite&&<div className="toast"><ShieldCheck size={15}/> Convite para {invite.role}</div>}<Field label="Data de nascimento"><input className="input" type="date" value={dob} onChange={e=>setDob(e.target.value)} required/></Field><Field label="Orixá"><select className="select" value={orixa} onChange={e=>setOrixa(e.target.value)} required><option value="">Escolha</option>{ORIXAS.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Grupo"><select className="select" value={group} onChange={e=>setGroup(e.target.value)} required><option value="">Escolha</option>{groups.filter(x=>x!=='Organização').map(x=><option key={x}>{x}</option>)}<option>Ainda não estou em nenhum grupo</option></select></Field></>}<Field label="E-mail"><input className="input" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></Field><Field label="Senha"><input className="input" type="password" minLength="6" value={password} onChange={e=>setPassword(e.target.value)} required/></Field><button className="btn primary" style={{width:'100%'}} disabled={busy}>{busy?'Aguarde…':register?'Criar minha conta':'Entrar'}</button></form><button className="btn" style={{width:'100%',marginTop:8}} onClick={()=>{setRegister(!register);setMessage('');setInvite(null)}}>{register?'Já tenho uma conta':'Tenho um código de convite'}</button></div></div>}
function Field({label,children}){return <div className="field"><label>{label}</label>{children}</div>}

function Home({p,go}){const[gira,setGira]=useState(null),[resp,setResp]=useState(null);const load=async()=>{const {data}=await supabase.from('giras').select('*').gte('starts_at',new Date().toISOString()).order('starts_at').limit(1).maybeSingle();setGira(data);if(data){const {data:r}=await supabase.from('gira_responses').select('*').eq('gira_id',data.id).eq('profile_id',p.id).maybeSingle();setResp(r)}};useEffect(()=>{load()},[p.id]);const answer=async status=>{const {data,error}=await supabase.from('gira_responses').upsert({gira_id:gira.id,profile_id:p.id,status},{onConflict:'gira_id,profile_id'}).select().single();if(!error)setResp(data)};return <><div className="hero"><span className="eyebrow">BEM-VINDO, {p.name?.split(' ')[0]?.toUpperCase()}</span><h1>Nossa força vem de quem veio antes<br/><em>e de quem caminha conosco.</em></h1><p className="muted">Acompanhe a vida da casa em um só lugar.</p></div>{gira?<div className="card"><div className="gira">{gira.art_path?<img className="art" src={gira.art_path} alt=""/>:<div className="art">🌿</div>}<div><span className="pill">PRÓXIMA GIRA</span><h2>{gira.name}</h2><p>{dateTime(gira.starts_at)}</p>{gira.what_to_bring&&<p className="muted small">Levar: {gira.what_to_bring}</p>}{Number(gira.contribution_amount)>0&&<p>Contribuição: <b>{money(gira.contribution_amount)}</b></p>}<button className="btn" onClick={()=>go('giras')}>Ver detalhes <ChevronRight size={15}/></button></div></div><div className="choice"><button className={'btn '+(resp?.status==='going'?'active':'')} onClick={()=>answer('going')}><Check size={15}/> Vou participar</button><button className={'btn '+(resp?.status==='not_going'?'active':'')} onClick={()=>answer('not_going')}><X size={15}/> Não vou</button></div></div>:<div className="card empty">Nenhuma próxima gira cadastrada.</div>}<Notice/><div className="grid"><Shortcut icon={CalendarDays} text="Giras" onClick={()=>go('giras')}/><Shortcut icon={Leaf} text="Comunidade" onClick={()=>go('community')}/><Shortcut icon={UserRound} text="Meu perfil" onClick={()=>go('me')}/><Shortcut icon={BookOpen} text="Informações da casa" onClick={()=>go('me')}/></div></>}
function Shortcut({icon:Icon,text,onClick}){return <button className="shortcut" onClick={onClick}><Icon/><b>{text}</b></button>}
function Notice(){const[n,setN]=useState(null);useEffect(()=>{supabase.from('notices').select('*').eq('published',true).order('starts_at',{ascending:false}).limit(1).maybeSingle().then(({data})=>setN(data))},[]);return n?<div className="card notice"><span className="eyebrow">AVISO DA CASA</span><b>{n.title}</b><p>{n.body}</p></div>:null}

function Giras({p}){const[giras,setGiras]=useState([]),[selected,setSelected]=useState(null);const load=async()=>{const {data}=await supabase.from('giras').select('*').order('starts_at');setGiras(data||[])};useEffect(()=>{load()},[]);if(selected)return <GiraDetail p={p} gira={selected} back={()=>setSelected(null)}/>;const months={};giras.forEach(g=>{const k=new Date(g.starts_at).toISOString().slice(0,7);(months[k]??=[]).push(g)});return <div><div className="row between"><div><span className="eyebrow">AGENDA</span><h1>Giras</h1></div><button className="btn" onClick={load}><RefreshCw size={15}/> Atualizar</button></div>{!giras.length&&<div className="card empty">Nenhuma gira cadastrada.</div>}{Object.entries(months).map(([m,items])=><section key={m}><h3 style={{textTransform:'capitalize'}}>{new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h3>{items.map(g=><button key={g.id} className="card" style={{width:'100%',textAlign:'left',cursor:'pointer'}} onClick={()=>setSelected(g)}><div className="gira">{g.art_path?<img className="art" src={g.art_path} alt=""/>:<div className="art">🌾</div>}<div><span className="pill">{new Date(g.starts_at)>=new Date()?'PRÓXIMA':'REALIZADA'}</span><h2>{g.name}</h2><p>{dateTime(g.starts_at)}</p></div></div></button>)}</section>)}</div>}
function GiraDetail({p,gira,back}){const[resp,setResp]=useState(null),[availability,setAvailability]=useState([]),[capacity,setCapacity]=useState([]),[tasks,setTasks]=useState([]),[posts,setPosts]=useState([]),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);const load=async()=>{const {data:r}=await supabase.from('gira_responses').select('*').eq('gira_id',gira.id).eq('profile_id',p.id).maybeSingle();setResp(r);if(r){const {data:a}=await supabase.from('gira_availability').select('period_key').eq('gira_response_id',r.id);setAvailability((a||[]).map(x=>x.period_key))}const [{data:c},{data:t},{data:ps}]=await Promise.all([supabase.rpc('gira_availability_summary',{p_gira_id:gira.id}),supabase.from('tasks').select('*,task_categories(name),task_assignments(profile_id,assignment_mode)').eq('gira_id',gira.id).order('sort_order'),supabase.from('community_posts').select('*').eq('gira_id',gira.id).order('created_at',{ascending:false})]);setCapacity(c||[]);setTasks(t||[]);setPosts(ps||[])};useEffect(()=>{load()},[gira.id,p.id]);const answer=async status=>{setBusy(true);const {data,error}=await supabase.from('gira_responses').upsert({gira_id:gira.id,profile_id:p.id,status},{onConflict:'gira_id,profile_id'}).select().single();if(error)setMsg(err(error));else{setResp(data);if(status==='not_going'){await supabase.from('gira_availability').delete().eq('gira_response_id',data.id);setAvailability([])}}setBusy(false);await load()};const toggle=async k=>{if(!resp||resp.status!=='going')return;const selected=availability.includes(k),summary=capacity.find(x=>x.period_key===k);if(!selected&&summary?.is_full){setMsg('Este período está completo.');return}setBusy(true);const {error}=await supabase.rpc('set_gira_availability',{p_gira_id:gira.id,p_period_key:k,p_available:!selected});if(error)setMsg(err(error));else{setAvailability(selected?availability.filter(x=>x!==k):[...availability,k]);setMsg('')}setBusy(false);await load()};const myTasks=tasks.filter(t=>(t.task_assignments||[]).some(a=>a.profile_id===p.id));const chooseLeaderTask=async taskId=>{setBusy(true);const {error}=await supabase.rpc('leader_choose_gira_task',{p_task_id:taskId});setMsg(error?err(error):'Tarefa escolhida.');setBusy(false);await load()};return <div><button className="btn" onClick={back}><ArrowLeft size={15}/> Todas as giras</button><div className="card"><div className="gira">{gira.art_path?<img className="art" src={gira.art_path} alt=""/>:<div className="art">🌾</div>}<div><span className="pill">GIRA</span><h2>{gira.name}</h2><p>{dateTime(gira.starts_at)}</p>{gira.what_to_bring&&<p>{gira.what_to_bring}</p>}{gira.notes&&<p className="muted">{gira.notes}</p>}{Number(gira.contribution_amount)>0&&<p>Contribuição: <b>{money(gira.contribution_amount)}</b></p>}</div></div>{msg&&<div className="toast">{msg}</div>}<div className="choice"><button className={'btn '+(resp?.status==='going'?'active':'')} disabled={busy} onClick={()=>answer('going')}><Check size={15}/> Vou participar</button><button className={'btn '+(resp?.status==='not_going'?'active':'')} disabled={busy} onClick={()=>answer('not_going')}><X size={15}/> Não vou</button></div>{resp?.status==='going'&&<><h3>Quero ajudar</h3><p className="muted small">Escolha os períodos em que você pode ajudar. As vagas consideram as tarefas cadastradas para cada período.</p><div className="choice">{periods.map(([k,l])=>{const s=capacity.find(x=>x.period_key===k),selected=availability.includes(k),full=s?.is_full&&!selected;return <button key={k} className={'btn '+(selected?'primary':'')} disabled={busy||full} onClick={()=>toggle(k)}>{l} · {selected?'Selecionado':full?'Completo':s?s.available_count+'/'+s.capacity+' vagas':'Sem vagas configuradas'}</button>})}</div></>}{myTasks.length>0&&<div className="card"><span className="eyebrow">MINHAS TAREFAS</span>{myTasks.map(t=><div className="row between" key={t.id}><span><b>{t.name}</b><small className="muted"> · {period(t.period_key)}</small></span><span className="pill">{t.task_assignments?.find(a=>a.profile_id===p.id)?.assignment_mode==='leader_choice'?'ESCOLHIDA':'ATRIBUÍDA'}</span></div>)}</div>}{resp?.status==='going'&&p.leadership_seal&&<div className="card"><span className="eyebrow">ESCOLHA DO LÍDER</span><p className="muted small">Você pode escolher uma tarefa em cada período que marcou como disponível. A escolha de liderança não ocupa as vagas regulares.</p>{periods.filter(([k])=>availability.includes(k)).map(([k,l])=>{const chosen=myTasks.find(t=>t.period_key===k&&t.task_assignments?.some(a=>a.profile_id===p.id&&a.assignment_mode==='leader_choice'));if(chosen)return <div className="list-item row between" key={k}><span><small className="muted">{l}</small><br/><b>{chosen.name}</b></span><span className="pill">ESCOLHIDA</span></div>;const options=tasks.filter(t=>t.period_key===k);return <div key={k} className="list-item"><small className="muted">{l}</small>{options.length?options.map(t=><div className="row between" key={t.id} style={{marginTop:8}}><span><b>{t.name}</b><small className="muted"> · {t.task_categories?.name||'Tarefa'}</small></span><button className="btn" disabled={busy} onClick={()=>chooseLeaderTask(t.id)}>Escolher</button></div>):<p className="muted small">Nenhuma tarefa cadastrada neste período.</p>}</div>})}</div>}</div><div className="card"><h3>O que ficou dessa gira?</h3>{posts.length?posts.map(x=><div className="list-item" key={x.id}><b>{kinds.find(k=>k[0]===x.kind)?.[1]}</b><p style={{whiteSpace:'pre-wrap'}}>{x.body}</p></div>):<p className="muted">Ainda não há registros ligados a esta gira.</p>}</div></div>}

function Community({p}){const[posts,setPosts]=useState([]),[giras,setGiras]=useState([]),[kind,setKind]=useState(''),[body,setBody]=useState(''),[giraId,setGiraId]=useState(''),[editing,setEditing]=useState(null),[msg,setMsg]=useState('');const load=async()=>{const {data}=await supabase.from('community_posts').select('*').order('created_at',{ascending:false});if(!data){setPosts([]);return}const ids=[...new Set(data.map(x=>x.author_id))];const gs=[...new Set(data.map(x=>x.gira_id).filter(Boolean))];const [{data:pr},{data:gr}]=await Promise.all([ids.length?supabase.from('profiles').select('id,name,orixa_symbol').in('id',ids):{data:[]},gs.length?supabase.from('giras').select('id,name').in('id',gs):{data:[]}]);const pm=Object.fromEntries((pr||[]).map(x=>[x.id,x])),gm=Object.fromEntries((gr||[]).map(x=>[x.id,x]));setPosts(data.map(x=>({...x,author:pm[x.author_id],gira:gm[x.gira_id]})))};useEffect(()=>{load();supabase.from('giras').select('id,name').order('starts_at',{ascending:false}).limit(30).then(({data})=>setGiras(data||[]))},[]);const save=async e=>{e.preventDefault();if(!kind||!body.trim()){setMsg('Escolha o tipo e escreva sua publicação.');return}const payload={kind,body:body.trim(),gira_id:giraId||null};const q=editing?supabase.from('community_posts').update(payload).eq('id',editing).eq('author_id',p.id):supabase.from('community_posts').insert({...payload,author_id:p.id});const {error}=await q;if(error)setMsg(err(error));else{setBody('');setGiraId('');setEditing(null);load()}};const remove=async id=>{if(!confirm('Excluir esta publicação?'))return;const {error}=await supabase.from('community_posts').delete().eq('id',id);if(error)setMsg(err(error));else load()};return <div><div className="hero" style={{paddingBottom:0}}><span className="eyebrow">NOSSA COMUNIDADE</span><h1>Mural da casa.</h1><p className="muted">Ensinamentos, reflexões e o que sentimos.</p></div><div className="card"><form onSubmit={save}><p className="muted small">Compartilhe ensinamentos, reflexões ou o que você sentiu. Toda publicação fica identificada pelo seu nome e Orixá.</p><div className="choice">{kinds.map(([v,l])=><button type="button" key={v} className={'btn '+(kind===v?'primary':'')} onClick={()=>setKind(v)}>{l}</button>)}</div><Field label="Texto"><textarea className="textarea" value={body} onChange={e=>setBody(e.target.value)} placeholder="Escreva para a comunidade…"/></Field><Field label="Gira (opcional)"><select className="select" value={giraId} onChange={e=>setGiraId(e.target.value)}><option value="">Nenhuma</option>{giras.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field>{msg&&<div className="toast">{msg}</div>}<div className="row"><button className="btn primary">{editing?'Salvar edição':'Publicar'}</button>{editing&&<button type="button" className="btn" onClick={()=>{setEditing(null);setBody('');setGiraId('')}}>Cancelar</button>}</div></form></div>{posts.filter(x=>!kind||x.kind===kind).map(post=><Post key={post.id} post={post} p={p} edit={()=>{setEditing(post.id);setKind(post.kind);setBody(post.body);setGiraId(post.gira_id||'')}} remove={()=>remove(post.id)}/>)}{!posts.length&&<div className="card empty">A comunidade ainda não tem publicações.</div>}</div>}
function Post({post,p,edit,remove}){const canEdit=post.author_id===p.id,canDelete=canEdit||p.role==='admin';return <div className="card"><div className="row between"><div className="row"><OrixaIcon name={post.author?.orixa_symbol} size={38}/><div><b>{post.author?.name||'Membro'}</b><div className="muted small">{kinds.find(k=>k[0]===post.kind)?.[1]}</div></div></div>{post.gira&&<span className="pill">{post.gira.name}</span>}</div><p style={{whiteSpace:'pre-wrap'}}>{post.body}</p>{(canEdit||canDelete)&&<div className="choice">{canEdit&&<button className="btn" onClick={edit}>Editar</button>}{canDelete&&<button className="btn danger" onClick={remove}><Trash2 size={14}/> Excluir</button>}</div>}</div>}

function Me({p,go,logout}){const[tab,setTab]=useState('menu');if(tab==='profile')return <Profile p={p} back={()=>setTab('menu')}/>;if(tab==='finance')return <Finance p={p} back={()=>setTab('menu')}/>;if(tab==='house')return <House back={()=>setTab('menu')}/>;return <div><div className="hero"><span className="eyebrow">EU</span><div className="row"><OrixaIcon name={p.orixa_symbol} size={60}/><div><h1>{p.name}</h1><p className="muted">{p.role} · {p.groups?.name||'Organização'}</p></div></div></div><div className="list"><button className="card list-item row between" onClick={()=>setTab('finance')}><span className="row"><WalletCards/> Meu financeiro</span><ChevronRight size={17}/></button><button className="card list-item row between" onClick={()=>setTab('house')}><span className="row"><BookOpen/> Informações da casa</span><ChevronRight size={17}/></button><button className="card list-item row between" onClick={()=>setTab('profile')}><span className="row"><UserRound/> Meu perfil</span><ChevronRight size={17}/></button>{(p.role==='admin'||p.role==='editor')&&<button className="card list-item row between" onClick={()=>go('admin')}><span className="row"><ShieldCheck/> Gestão da casa</span><ChevronRight size={17}/></button>}<button className="card list-item row" onClick={logout}><LogOut/> Sair</button></div></div>}
function Profile({p,back}){const[name,setName]=useState(p.name),[dob,setDob]=useState(p.date_of_birth||''),[orixa,setOrixa]=useState(p.orixa_symbol),[group,setGroup]=useState(p.groups?.name||'Organização'),[message,setMessage]=useState('');const save=async()=>{const {error}=await supabase.rpc('update_my_profile',{p_name:name,p_date_of_birth:dob,p_orixa_symbol:orixa,p_group_name:group});setMessage(error?err(error):'Perfil atualizado.')};return <div><button className="btn" onClick={back}><ArrowLeft size={15}/> Eu</button><div className="card"><h2>Meu perfil</h2><p className="muted small">Você pode atualizar seus dados pessoais e sua identificação na casa.</p><Field label="Nome"><input className="input" value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Data de nascimento"><input className="input" type="date" value={dob} onChange={e=>setDob(e.target.value)}/></Field><Field label="Orixá"><select className="select" value={orixa} onChange={e=>setOrixa(e.target.value)}>{ORIXAS.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Grupo"><select className="select" value={group} onChange={e=>setGroup(e.target.value)}>{groups.map(g=><option key={g}>{g}</option>)}</select></Field>{message&&<div className="toast">{message}</div>}<button className="btn primary" onClick={save}><Save size={14}/> Salvar alterações</button></div></div>}function Finance({p,back}){const[dues,setDues]=useState([]),[charges,setCharges]=useState([]),[loading,setLoading]=useState(true);const load=async()=>{setLoading(true);const [{data:d},{data:c}]=await Promise.all([supabase.from('monthly_dues').select('*').eq('profile_id',p.id).order('reference_month',{ascending:false}),supabase.from('extra_charges').select('*').eq('profile_id',p.id).order('due_date',{ascending:false})]);setDues(d||[]);setCharges(c||[]);setLoading(false)};useEffect(()=>{load()},[p.id]);const monthLabel=x=>new Date(x+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return <div><button className="btn" onClick={back}><ArrowLeft size={15}/> Eu</button><div className="row between"><div><span className="eyebrow">MEU FINANCEIRO</span><h2>Financeiro</h2></div><button className="btn" onClick={load}><RefreshCw size={14}/> Atualizar</button></div>{loading?<div className="card muted">Carregando…</div>:<><div className="card"><h3>Mensalidades</h3>{dues.length?dues.map(x=><div className="list-item row between" key={x.id}><span>{monthLabel(x.reference_month)}</span><span className="pill">{x.status==='paid'?'PAGO':'NÃO PAGO'}</span></div>):<p className="muted">Nenhuma mensalidade lançada.</p>}</div><div className="card"><h3>Outras cobranças</h3>{charges.length?charges.map(x=><div className="list-item" key={x.id}><div className="row between"><b>{x.description}</b><b>{money(x.amount)}</b></div><div className="muted small">{x.due_date?'Vencimento '+new Date(x.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem vencimento'} · {x.status==='paid'?'Pago':'Não pago'}</div></div>):<p className="muted">Nenhuma outra cobrança.</p>}</div></>}</div>}
function House({back}){const[items,setItems]=useState([]);useEffect(()=>{supabase.from('house_contents').select('*').order('sort_order').then(({data})=>setItems(data||[]))},[]);return <div><button className="btn" onClick={back}><ArrowLeft size={15}/> Eu</button><h2>Informações da casa</h2>{items.map(x=><div className="card" key={x.id}><span className="pill">{x.content_type||'INFORMAÇÃO'}</span><h3>{x.title}</h3><p style={{whiteSpace:'pre-wrap'}}>{x.body}</p></div>)}{!items.length&&<div className="card empty">Nenhum conteúdo publicado.</div>}</div>}
function Birthday(){const[people,setPeople]=useState([]);useEffect(()=>{const month=new Date().getMonth()+1;supabase.from('profiles').select('id,name,date_of_birth,orixa_symbol').eq('is_active',true).then(({data})=>setPeople((data||[]).filter(x=>x.date_of_birth&&new Date(x.date_of_birth+'T12:00:00').getMonth()+1===month)))},[]);if(!people.length)return null;return <div style={{maxWidth:900,margin:'0 auto',padding:'0 16px 90px'}}><div className="card"><span className="eyebrow">ANIVERSARIANTES DO MÊS</span><div className="row">{people.map(x=><div className="list-item" key={x.id}><div className="row"><OrixaIcon name={x.orixa_symbol} size={28}/><div><b>{x.name}</b><div className="muted small">{new Date(x.date_of_birth+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</div></div></div></div>)}</div></div></div>}

function Admin({p,editor=false}){const[tab,setTab]=useState(editor?'giras':'overview');const nav=editor?[['giras','Giras'],['tasks','Tarefas']]:[['overview','Visão'],['people','Pessoas'],['giras','Giras'],['tasks','Tarefas'],['finance','Financeiro'],['invites','Convites'],['content','Conteúdos']];return <div><div className="card" style={{marginBottom:12}}><div className="row"><ShieldCheck size={18}/><div><b>{editor?'Gestão da casa':'Administração'}</b><div className="muted small">{editor?'Giras e tarefas':'Pessoas, giras, tarefas, financeiro e conteúdos'}</div></div></div></div><div className="admin-nav">{nav.map(([id,label])=><button className={'btn '+(tab===id?'primary':'')} key={id} onClick={()=>setTab(id)}>{label}</button>)}</div>{tab==='overview'&&<AdminOverview/>}{tab==='people'&&<People/>}{tab==='giras'&&<GiraManager p={p} editor={editor}/>} {tab==='tasks'&&<TaskManager editor={editor}/>} {tab==='finance'&&<AdminFinance/>}{tab==='invites'&&<Invites/>}{tab==='content'&&<Content/>}</div>}
function AdminOverview(){return <div><h2>Visão geral</h2><div className="card">Acesso administrativo ativo.</div></div>}
function GiraManager({p,editor}){const[giras,setGiras]=useState([]),[form,setForm]=useState({name:'',starts_at:'',what_to_bring:'',contribution_amount:'',contribution_due_date:'',notes:'',art_path:''}),[editing,setEditing]=useState(null),[artFile,setArtFile]=useState(null),[attendance,setAttendance]=useState(null),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 const empty={name:'',starts_at:'',what_to_bring:'',contribution_amount:'',contribution_due_date:'',notes:'',art_path:''};
 const load=async()=>{const {data}=await supabase.from('giras').select('*').order('starts_at',{ascending:false});setGiras(data||[])};
 useEffect(()=>{load()},[]);
 const uploadArt=async(id)=>{if(!artFile)return form.art_path||null;const ext=(artFile.name.split('.').pop()||'jpg').toLowerCase();const path=id+'/'+crypto.randomUUID()+'.'+ext;const {error}=await supabase.storage.from('gira-art').upload(path,artFile,{upsert:true,contentType:artFile.type});if(error)throw error;return supabase.storage.from('gira-art').getPublicUrl(path).data.publicUrl};
 const save=async()=>{setMessage('');setBusy(true);try{if(!form.name||!form.starts_at)throw new Error('Informe nome, data e hora.');let id=editing;let art=form.art_path||null;if(!id){const {data,error}=await supabase.rpc('create_gira',{p_name:form.name,p_starts_at:new Date(form.starts_at).toISOString(),p_what_to_bring:form.what_to_bring,p_contribution_amount:Number(form.contribution_amount||0),p_contribution_due_date:form.contribution_due_date||null,p_notes:form.notes});if(error)throw error;id=data;art=await uploadArt(id);if(art){const u=await supabase.rpc('update_gira',{p_gira_id:id,p_name:form.name,p_starts_at:new Date(form.starts_at).toISOString(),p_what_to_bring:form.what_to_bring,p_contribution_amount:Number(form.contribution_amount||0),p_contribution_due_date:form.contribution_due_date||null,p_notes:form.notes,p_art_path:art});if(u.error)throw u.error}}else{art=await uploadArt(id);const {error}=await supabase.rpc('update_gira',{p_gira_id:id,p_name:form.name,p_starts_at:new Date(form.starts_at).toISOString(),p_what_to_bring:form.what_to_bring,p_contribution_amount:Number(form.contribution_amount||0),p_contribution_due_date:form.contribution_due_date||null,p_notes:form.notes,p_art_path:art});if(error)throw error}setForm(empty);setArtFile(null);setEditing(null);setMessage('Gira salva.');load()}catch(e){setMessage(err(e))}finally{setBusy(false)}};
 const remove=async id=>{if(!confirm('Excluir esta gira?'))return;const {error}=await supabase.rpc('delete_gira',{p_gira_id:id});if(error)setMessage(err(error));else{if(attendance?.id===id)setAttendance(null);load()}};
 const showAttendance=async id=>{setAttendance({id,loading:true});const {data,error}=await supabase.rpc('editor_gira_attendance',{p_gira_id:id});if(error)setMessage(err(error));setAttendance({id,rows:data||[]})};
 return <div><div className="row between"><h2>Giras</h2><button className="btn" onClick={()=>{setEditing(null);setForm(empty);setArtFile(null)}}><Plus size={14}/> Nova gira</button></div>{message&&<div className="toast">{message}</div>}<div className="card"><Field label="Nome"><input className="input" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Data e hora"><input className="input" type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="O que levar"><textarea className="textarea" value={form.what_to_bring} onChange={e=>setForm({...form,what_to_bring:e.target.value})}/></Field><div className="grid"><Field label="Contribuição"><input className="input" type="number" step="0.01" min="0" value={form.contribution_amount} onChange={e=>setForm({...form,contribution_amount:e.target.value})}/></Field><Field label="Vencimento"><input className="input" type="date" value={form.contribution_due_date} onChange={e=>setForm({...form,contribution_due_date:e.target.value})}/></Field></div><Field label="Observações"><textarea className="textarea" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field><Field label="Arte da gira"><input className="input" type="file" accept="image/*" onChange={e=>setArtFile(e.target.files?.[0]||null)}/>{form.art_path&&<img className="art" src={form.art_path} alt="" style={{marginTop:8}}/>}</Field><button className="btn primary" disabled={busy} onClick={save}><Save size={14}/> {busy?'Salvando…':editing?'Salvar edição':'Criar gira'}</button></div>{giras.map(g=><div className="card" key={g.id}><div className="row between"><div className="row"><div>{g.art_path?<img className="art" src={g.art_path} alt=""/>:<div className="art">🌾</div>}</div><div><b>{g.name}</b><div className="muted small">{dateTime(g.starts_at)}</div></div></div><div className="choice"><button className="btn" onClick={()=>{setEditing(g.id);setForm({name:g.name,starts_at:g.starts_at.slice(0,16),what_to_bring:g.what_to_bring||'',contribution_amount:g.contribution_amount||'',contribution_due_date:g.contribution_due_date||'',notes:g.notes||'',art_path:g.art_path||''});setArtFile(null)}}>Editar</button><button className="btn" onClick={()=>showAttendance(g.id)}><Users size={14}/> Participantes</button><button className="btn danger" onClick={()=>remove(g.id)}><Trash2 size={14}/></button></div></div>{attendance?.id===g.id&&<div className="card"><h3>Participação</h3>{attendance.loading?<p className="muted">Carregando…</p>:attendance.rows?.length?<div><div className="choice"><span className="pill">VAI {attendance.rows.filter(r=>r.status==='going').length}</span><span className="pill">NÃO VAI {attendance.rows.filter(r=>r.status==='not_going').length}</span><span className="pill">AINDA NÃO RESPONDEU {attendance.rows.filter(r=>r.status==='no_response').length}</span></div><div className="list">{attendance.rows.map(r=><div className="list-item row between" key={r.profile_id}><span><b>{r.name}</b><div className="muted small">{r.status==='going'?(r.periods?.length?'Disponível: '+r.periods.map(period).join(', '):'Vai participar · sem disponibilidade informada'):r.status==='not_going'?'Não vai':'Ainda não respondeu'}</div></span><span className="pill">{r.status==='going'?'VAI':r.status==='not_going'?'NÃO VAI':'SEM RESPOSTA'}</span></div>)}</div></div>:<p className="muted">Nenhum membro ativo cadastrado.</p>}</div>}</div>)}</div>}
function TaskManager({editor=false}){const[giras,setGiras]=useState([]),[giraId,setGiraId]=useState(''),[tasks,setTasks]=useState([]),[cats,setCats]=useState([]),[people,setPeople]=useState([]),[responses,setResponses]=useState([]),[message,setMessage]=useState('');const loadGiras=async()=>{const {data}=await supabase.from('giras').select('*').order('starts_at',{ascending:false});setGiras(data||[]);if(!giraId&&data?.[0])setGiraId(data[0].id)};const loadTasks=async()=>{if(!giraId)return;const [{data:t},{data:c},{data:p},{data:r}]=await Promise.all([supabase.from('tasks').select('*,task_categories(name),task_assignments(id,profile_id,assignment_mode)').eq('gira_id',giraId).order('period_key').order('sort_order'),supabase.from('task_categories').select('*').order('name'),supabase.from('profiles').select('id,name,is_iniciado,leadership_seal,groups(name)').eq('is_active',true).order('name'),supabase.from('gira_responses').select('profile_id,status').eq('gira_id',giraId)]);setTasks(t||[]);setCats(c||[]);setPeople(p||[]);setResponses(r||[])};useEffect(()=>{loadGiras()},[]);useEffect(()=>{loadTasks()},[giraId]);const add=async()=>{if(!giraId||!cats[0])return;const {error}=await supabase.rpc('editor_create_task',{p_gira_id:giraId,p_name:'Nova tarefa',p_period_key:'friday',p_slots:1,p_category_id:cats[0].id,p_sort_order:999});if(error)setMessage(err(error));else{setMessage('Tarefa criada.');loadTasks()}};const draw=async()=>{if(!giraId)return;const {data,error}=await supabase.rpc('draw_gira_tasks',{p_gira_id:giraId});setMessage(error?err(error):`Sorteio concluído: ${data?.assigned||0} atribuições regulares.`);loadTasks()};const eligible=people.filter(p=>responses.some(r=>r.profile_id===p.id&&r.status==='going')&&p.leadership_seal===null);const regularAssigned=tasks.reduce((n,t)=>n+(t.task_assignments||[]).filter(a=>a.assignment_mode!=='leader_choice').length,0);const leaderAssigned=tasks.reduce((n,t)=>n+(t.task_assignments||[]).filter(a=>a.assignment_mode==='leader_choice').length,0);const withoutTask=eligible.filter(p=>!tasks.some(t=>(t.task_assignments||[]).some(a=>a.profile_id===p.id&&a.assignment_mode!=='leader_choice')));return <div><div className="row between"><div><span className="eyebrow">OPERAÇÃO</span><h2>Tarefas</h2></div><div className="row"><select className="select" value={giraId} onChange={e=>setGiraId(e.target.value)}>{giras.map(g=><option value={g.id} key={g.id}>{g.name} · {dateTime(g.starts_at)}</option>)}</select><button className="btn" onClick={add}><Plus size={14}/> Tarefa</button>{!editor&&<button className="btn primary" onClick={draw}><RefreshCw size={14}/> Sortear regulares</button>}</div></div>{message&&<div className="toast">{message}</div>}<div className="card"><span className="eyebrow">ACOMPANHAMENTO</span><div className="row"><span className="pill">{regularAssigned} atribuições regulares</span><span className="pill">{leaderAssigned} escolhas de liderança</span><span className="pill">{withoutTask.length} presentes sem tarefa regular</span><span className="pill">{eligible.length} presentes elegíveis</span></div>{withoutTask.length>0&&<p className="muted small" style={{marginTop:10}}><b>Presentes sem tarefa regular:</b> {withoutTask.map(x=>x.name).join(', ')}</p>}<p className="muted small">As escolhas de liderança são adicionais e não ocupam as vagas regulares.</p></div>{tasks.map(t=><TaskRow key={t.id} task={t} cats={cats} people={people} responses={responses} editor={editor} refresh={loadTasks}/>)}</div>}

function TaskRow({task,cats,people,responses,editor,refresh}){const[x,setX]=useState(task),[message,setMessage]=useState('');const save=async()=>{const {error}=await supabase.rpc('update_task',{p_task_id:x.id,p_name:x.name,p_period_key:x.period_key,p_slots:Number(x.slots),p_category_id:x.category_id,p_sort_order:Number(x.sort_order||0)});setMessage(error?err(error):'Salvo.');refresh()};const assign=async id=>{const {error}=await supabase.rpc(editor?'editor_assign_task':'admin_assign_task',{p_task_id:x.id,p_profile_id:id,p_mode:'manual'});setMessage(error?err(error):'Pessoa atribuída.');refresh()};const removeAssignment=async id=>{const {error}=await supabase.rpc('admin_remove_task_assignment',{p_assignment_id:id});setMessage(error?err(error):'Atribuição removida.');refresh()};const remove=async()=>{if(!confirm('Excluir esta tarefa?'))return;const {error}=await supabase.rpc('admin_delete_task',{p_task_id:x.id});setMessage(error?err(error):'Tarefa excluída.');refresh()};const assigned=x.task_assignments||[],regular=assigned.filter(a=>a.assignment_mode!=='leader_choice'),leaders=assigned.filter(a=>a.assignment_mode==='leader_choice'),going=people.filter(q=>q.leadership_seal===null&&responses.some(r=>r.profile_id===q.id&&r.status==='going'));return <div className="card"><div className="grid"><Field label="Tarefa"><input className="input" value={x.name} onChange={e=>setX({...x,name:e.target.value})}/></Field><Field label="Período"><select className="select" value={x.period_key} onChange={e=>setX({...x,period_key:e.target.value})}>{periods.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Vagas regulares"><input className="input" type="number" min="1" value={x.slots} onChange={e=>setX({...x,slots:e.target.value})}/></Field><Field label="Categoria"><select className="select" value={x.category_id||''} onChange={e=>setX({...x,category_id:e.target.value})}>{cats.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field></div><div className="muted small">Regulares: {regular.length}/{x.slots} · Vagas restantes: {Math.max(0,Number(x.slots)-regular.length)}{leaders.length>0&&<> · Lideranças: {leaders.map(a=>people.find(q=>q.id===a.profile_id)?.name||'Pessoa').join(', ')}</>}</div>{regular.length>0&&<div className="list" style={{marginTop:10}}>{regular.map(a=><div className="list-item row between" key={a.id}><span>{people.find(q=>q.id===a.profile_id)?.name||'Pessoa'} {people.find(q=>q.id===a.profile_id)?.is_iniciado?' · Iniciado':''}</span><button className="btn danger" onClick={()=>removeAssignment(a.id)}>Remover</button></div>)}</div>}<Field label="Atribuir tarefa regular"><select className="select" value="" onChange={e=>e.target.value&&assign(e.target.value)}><option value="">Escolher pessoa…</option>{going.filter(q=>!assigned.some(a=>a.profile_id===q.id)).map(q=><option value={q.id} key={q.id}>{q.name}{q.is_iniciado?' · Iniciado':''}</option>)}</select></Field>{message&&<div className="toast">{message}</div>}<div className="row"><button className="btn primary" onClick={save}><Save size={14}/> Salvar</button><button className="btn danger" onClick={remove}><Trash2 size={14}/> Excluir</button></div></div>}

function People(){const[people,setPeople]=useState([]),[groupsData,setGroups]=useState([]),[message,setMessage]=useState('');const load=async()=>{const [{data:p},{data:g}]=await Promise.all([supabase.from('profiles').select('*,groups(name)').order('name'),supabase.from('groups').select('*').order('name')]);setPeople(p||[]);setGroups(g||[])};useEffect(()=>{load()},[]);const save=async x=>{setMessage('');const {error}=await supabase.rpc('admin_update_profile',{p_profile_id:x.id,p_role:x.role,p_group_id:x.group_id||null,p_leadership_seal:x.leadership_seal||null,p_is_iniciado:!!x.is_iniciado,p_is_active:x.is_active!==false});if(error)setMessage(err(error));else{setMessage('Pessoa atualizada.');load()}};return <div><div className="row between"><div><span className="eyebrow">ADMINISTRAÇÃO</span><h2>Pessoas</h2></div><span className="pill">{people.filter(x=>x.is_active).length} ativos</span></div>{message&&<div className="toast">{message}</div>}{people.map(p=><Person key={p.id} p={p} groupsData={groupsData} save={save}/>)}</div>}
function Person({p,groupsData,save}){const[x,setX]=useState({...p,group_id:p.group_id||p.groups?.id||'',leadership_seal:p.leadership_seal||''});return <div className="card"><div className="row"><OrixaIcon name={p.orixa_symbol} size={35}/><div><b>{p.name}</b><div className="muted small">{p.email}</div><div className="muted small">{p.is_active?'Membro ativo':'Cadastro inativo'}</div></div></div><div className="grid"><Field label="Perfil"><select className="select" value={x.role} onChange={e=>setX({...x,role:e.target.value})}><option>member</option><option>editor</option><option>admin</option></select></Field><Field label="Grupo"><select className="select" value={x.group_id||''} onChange={e=>setX({...x,group_id:e.target.value})}><option value="">Organização</option>{groupsData.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><Field label="Selo de liderança"><select className="select" value={x.leadership_seal||''} onChange={e=>setX({...x,leadership_seal:e.target.value})}><option value="">Sem selo</option><option value="lider">Liderança</option><option value="cozinha">Liderança · Cozinha</option><option value="terreiro">Liderança · Terreiro</option></select></Field></div><div className="choice"><label className="btn"><input type="checkbox" checked={!!x.is_iniciado} onChange={e=>setX({...x,is_iniciado:e.target.checked})}/> Iniciado</label><label className="btn"><input type="checkbox" checked={x.is_active!==false} onChange={e=>setX({...x,is_active:e.target.checked})}/> Ativo</label><button className="btn primary" onClick={()=>save(x)}>Salvar</button></div></div>}function AdminFinance(){const[people,setPeople]=useState([]),[dues,setDues]=useState([]),[charges,setCharges]=useState([]),[month,setMonth]=useState(new Date().toISOString().slice(0,7)),[description,setDescription]=useState(''),[amount,setAmount]=useState(''),[dueDate,setDueDate]=useState(''),[target,setTarget]=useState('all'),[message,setMessage]=useState('');const load=async()=>{const [{data:p},{data:d},{data:c}]=await Promise.all([supabase.from('profiles').select('id,name').eq('is_active',true).order('name'),supabase.from('monthly_dues').select('*').order('reference_month',{ascending:false}).limit(1000),supabase.from('extra_charges').select('*').order('due_date',{ascending:false}).limit(1000)]);setPeople(p||[]);setDues(d||[]);setCharges(c||[])};useEffect(()=>{load()},[]);const toggle=async p=>{const ref=month+'-01';const current=dues.find(x=>x.profile_id===p.id&&x.reference_month===ref);const {error}=await supabase.rpc('admin_set_monthly_dues',{p_profile_id:p.id,p_reference_month:ref,p_status:current?.status==='paid'?'unpaid':'paid'});if(error)setMessage(err(error));else load()};const createCharge=async()=>{setMessage('');if(!description.trim()||Number(amount)<0){setMessage('Informe descrição e valor.');return}const ids=target==='all'?people.map(x=>x.id):[target];for(const id of ids){const {error}=await supabase.rpc('create_extra_charge',{p_profile_id:id,p_description:description.trim(),p_amount:Number(amount),p_due_date:dueDate||null,p_gira_id:null});if(error){setMessage(err(error));return}}setDescription('');setAmount('');setDueDate('');setTarget('all');setMessage('Cobrança criada.');load()};const setChargeStatus=async x=>{const {error}=await supabase.rpc('admin_set_extra_charge_status',{p_charge_id:x.id,p_status:x.status==='paid'?'unpaid':'paid'});if(error)setMessage(err(error));else load()};const labelMonth=new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return <div><h2>Financeiro</h2>{message&&<div className="toast">{message}</div>}<div className="card"><div className="row between"><h3>Mensalidades</h3><input className="input" style={{maxWidth:180}} type="month" value={month} onChange={e=>setMonth(e.target.value)}/></div><p className="muted small">Status de {labelMonth} · clique para alternar.</p>{people.map(p=>{const d=dues.find(x=>x.profile_id===p.id&&x.reference_month===month+'-01');return <div className="list-item row between" key={p.id}><span>{p.name}</span><button className="btn" onClick={()=>toggle(p)}>{d?.status==='paid'?'Pago':'Não pago'}</button></div>})}</div><div className="card"><h3>Nova cobrança</h3><Field label="Descrição"><input className="input" value={description} onChange={e=>setDescription(e.target.value)} placeholder="Ex.: material da gira"/></Field><div className="grid"><Field label="Valor"><input className="input" type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field label="Vencimento"><input className="input" type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></Field></div><Field label="Pessoa"><select className="select" value={target} onChange={e=>setTarget(e.target.value)}><option value="all">Todos os membros ativos</option>{people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><button className="btn primary" onClick={createCharge}><Plus size={14}/> Criar cobrança</button></div><div className="card"><h3>Outras cobranças</h3>{charges.length?charges.map(x=><div className="list-item row between" key={x.id}><span><b>{people.find(p=>p.id===x.profile_id)?.name||'Pessoa'}</b><div className="muted small">{x.description} · {money(x.amount)} · {x.due_date?'vence '+new Date(x.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'sem vencimento'}</div></span><button className="btn" onClick={()=>setChargeStatus(x)}>{x.status==='paid'?'Pago':'Não pago'}</button></div>):<p className="muted">Nenhuma cobrança adicional.</p>}</div></div>}
function Invites(){const[items,setItems]=useState([]),[role,setRole]=useState('member'),[code,setCode]=useState(''),[message,setMessage]=useState('');const load=async()=>{const {data}=await supabase.from('invitations').select('*').order('created_at',{ascending:false});setItems(data||[])};useEffect(()=>{load()},[]);const create=async()=>{const {data,error}=await supabase.rpc('admin_create_invitation',{p_role:role,p_intended_name:null,p_intended_email:null});if(error)setMessage(err(error));else{setCode(Array.isArray(data)?data[0]?.code:data?.code);load()}};return <div><h2>Convites</h2>{code&&<div className="toast"><b>Novo código:</b> {code}</div>}{message&&<div className="toast">{message}</div>}<div className="card"><Field label="Perfil"><select className="select" value={role} onChange={e=>setRole(e.target.value)}><option value="member">Membro</option><option value="editor">Editor</option><option value="admin">Administrador</option></select></Field><button className="btn primary" onClick={create}><Plus size={14}/> Criar convite</button></div>{items.map(x=><div className="card" key={x.id}><b>{x.code}</b><div className="muted small">{x.role} · {x.status}</div></div>)}</div>}
function Content(){const[items,setItems]=useState([]),[title,setTitle]=useState(''),[body,setBody]=useState(''),[message,setMessage]=useState(''),[editing,setEditing]=useState(null);const load=async()=>{const {data}=await supabase.from('house_contents').select('*').order('sort_order');setItems(data||[])};useEffect(()=>{load()},[]);const create=async()=>{const {error}=await supabase.rpc('admin_create_house_content',{p_title:title,p_body:body,p_sort_order:items.length});if(error)setMessage(err(error));else{setTitle('');setBody('');load()}};return <div><h2>Conteúdos da casa</h2>{message&&<div className="toast">{message}</div>}<div className="card"><Field label="Título"><input className="input" value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="Texto"><textarea className="textarea" value={body} onChange={e=>setBody(e.target.value)}/></Field><button className="btn primary" onClick={create}><Plus size={14}/> Publicar</button></div>{items.map(x=><div className="card" key={x.id}><span className="pill">{x.content_type}</span><h3>{x.title}</h3><p>{x.body}</p></div>)}</div>}

createRoot(document.getElementById('root')).render(<App/>)

